//! Fixed container workflow. Builds and cloud lifecycle run outside this process.
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},process::{Command,Stdio}};
#[path="/tmp/zopro-ready-arithmetic/observations.rs"] mod observations;
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn run(args:&[String],out:&Path){let log=fs::File::create(out).unwrap();let err=log.try_clone().unwrap();let status=Command::new(&args[0]).args(&args[1..]).stdout(Stdio::from(log)).stderr(Stdio::from(err)).status().unwrap();assert!(status.success(),"command failed, see {}",out.display());}
fn snapshots()->Value{let mut values=BTreeMap::new();for path in["/proc/loadavg","/sys/fs/cgroup/cpu.stat","/sys/fs/cgroup/cpu.max","/sys/fs/cgroup/memory.max","/sys/fs/cgroup/memory.events","/sys/fs/cgroup/memory.swap.events","/sys/fs/cgroup/memory.swap.max"]{if let Ok(s)=fs::read_to_string(path){values.insert(path,s);}}json!(values)}
fn walk_proofs(p:&Path,files:&mut Vec<std::path::PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir(){walk_proofs(&p,files);}else if p.extension().is_some_and(|x|x=="proof"){files.push(p);}}}
fn main(){let phase=std::env::args().nth(1).unwrap();assert!(phase=="preflight"||phase=="measure");let root=Path::new("/output");let dir=root.join(&phase);fs::create_dir(&dir).unwrap();let manifest=read("/ready/manifest.json");let mut pins:BTreeMap<String,String>=serde_json::from_value(manifest["container_pins"].clone()).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h,"container pin {p}");}
 let mut prior:BTreeSet<String>=serde_json::from_value(manifest["prior_proof_sha256"].clone()).unwrap();
 let mut environment=manifest["environment"].clone();environment["ZOPRO_CPU_LAGRANGE_DIR"]=json!("/output/lagrange-cache");environment["ZOPRO_BASIS_KEY_DIR"]=json!("/ready-basis");
 let mut cases=Vec::new();for shape in["1x2","8x2"]{let base=&manifest["cases"][shape];for workers in if phase=="preflight"{vec![4]}else{vec![16,32,64,96]}{let mut c=base.clone();c["name"]=json!(format!("{shape}-w{workers}"));c["workers"]=json!(workers);c["cpu_affinity"]=json!(format!("0-{}",workers-1));c["rounds"]=json!(if shape=="1x2"{31}else{17});c["profile_rounds"]=json!(51);cases.push(c);}}
 let variants:Vec<_>=["accepted","off","on","aeglos"].iter().map(|engine|json!({"name":engine,"binary":"/usr/local/bin/ready-adapter","environment":{"ZOPRO_READY_ENGINE":engine}})).collect();
 save(dir.join("before.json"),&snapshots());let cpu=Command::new("lscpu").output().unwrap();assert!(cpu.status.success());fs::write(dir.join("lscpu.txt"),cpu.stdout).unwrap();let topology=Command::new("lscpu").args(["-e=CPU,CORE,SOCKET,NODE"]).output().unwrap();assert!(topology.status.success());fs::write(dir.join("topology.txt"),topology.stdout).unwrap();
 if phase=="preflight"{let mut steps=Vec::new();for c in &cases{let stem=Path::new(c["image"].as_str().unwrap()).file_stem().unwrap();for variant in &variants{let name=format!("{}-{}",c["name"].as_str().unwrap(),variant["name"].as_str().unwrap());let proofroot=dir.join("proofs").join(&name);let proofdir=proofroot.join(stem);let mut env=environment.clone();env["RAYON_NUM_THREADS"]=json!("4");env["ZOPRO_READY_ENGINE"]=variant["name"].clone();steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c","0-3","/usr/local/bin/ready-adapter",c["image"],c["request"],"1",proofdir],"environment":env,"timeout_seconds":300}));steps.push(json!({"kind":"command","name":format!("verify-{name}"),"argv":["/usr/local/bin/gnark-verify","/keys",proofroot,"/manifest/zopro-keys.lock"],"timeout_seconds":120}));}}
  save(dir.join("pins.json"),&json!(pins));save(dir.join("workflow.json"),&json!({"version":1,"environment":{},"source_pins":dir.join("pins.json"),"steps":steps}));run(&["/usr/local/bin/ready-xtask".into(),"workflow".into(),dir.join("workflow.json").to_str().unwrap().into(),dir.join("workflow").to_str().unwrap().into()],&dir.join("workflow.log"));
  let mut files=Vec::new();walk_proofs(&dir.join("proofs"),&mut files);assert_eq!(files.len(),8);let mut inventory=BTreeMap::new();let mut traced=0;for p in files{assert_eq!(fs::metadata(&p).unwrap().len(),164);let h=hash(&p);assert!(prior.insert(h.clone()));inventory.insert(p.to_str().unwrap().to_owned(),h);let public=p.with_extension("public");let stem=p.parent().unwrap().file_name().unwrap();let c=cases.iter().find(|c|Path::new(c["image"].as_str().unwrap()).file_stem().unwrap()==stem).unwrap();assert_eq!(hash(&public),c["public_sha256"].as_str().unwrap());inventory.insert(public.to_str().unwrap().to_owned(),hash(public));let trace=p.parent().unwrap().join("readiness.json");if trace.exists(){let v=read(trace);assert_eq!(v.as_array().unwrap().len(),1);observations::inspect(&v[0],4);traced+=1;}}assert_eq!(traced,2);
  save(dir.join("proof-inventory.json"),&json!(inventory));save(dir.join("complete.json"),&json!({"sdk_requests":32,"distinct_gnark_exports":8,"prior_after":prior,"after":snapshots(),"status":"complete"}));
 }else{let preflight=read("/ready/preflight-complete.json");assert_eq!(preflight["status"],"complete");for h in preflight["new_proof_sha256"].as_array().unwrap(){assert!(prior.insert(h.as_str().unwrap().to_owned()));}pins.insert("/ready/preflight-complete.json".into(),hash("/ready/preflight-complete.json"));
  let config=json!({"version":1,"blocks":3,"profile_blocks":1,"profile_cases":["1x2-w32","1x2-w96"],"command":["{binary}","{image}","{request}","{rounds}","{proof_dir}/{stem}"],"variants":variants,"cases":cases,"pins":pins,"prior_proof_sha256":prior,"verifier":["/usr/local/bin/gnark-verify","/keys","{proof_dir}","/manifest/zopro-keys.lock"],"profile_environment":{"ZOPRO_BENCH_PERF_CTL":"{control}","ZOPRO_BENCH_PERF_ACK":"{ack}"},"environment":environment,"checks":[],"child_prefix":[],"perf_prefix":[],"perf":"perf","frequency_hz":199,"monotonic_clock":true,"symbol_categories":manifest["symbol_categories"],"timeout_seconds":300});save(dir.join("config.json"),&config);
  run(&["/usr/local/bin/ready-xtask".into(),"perf".into(),dir.join("config.json").to_str().unwrap().into(),dir.join("performance").to_str().unwrap().into()],&dir.join("workflow.log"));let rows=read(dir.join("performance/rows.json"));assert_eq!(rows.as_array().unwrap().len(),104);let sdk:usize=rows.as_array().unwrap().iter().map(|r|r["samples_ms"].as_array().unwrap().len()+3).sum();assert_eq!(sdk,3024);save(dir.join("complete.json"),&json!({"status":"complete","sdk_requests":sdk,"distinct_gnark_exports":104,"after":snapshots()}));
 }println!("{phase} complete");}
